class Vector2D {
  private final int[][] vec;
  private int row, col;

  public Vector2D(int[][] vec) {
    this.vec = vec;
  }

  public int next() {
    hasNext();
    return vec[row][col++];
  }

  public boolean hasNext() {
    while (row < vec.length && col == vec[row].length) {
      row++;
      col = 0;
    }
    return row < vec.length;
  }
}
